     1	package domain;
     2	
     3	import java.time.LocalDate;
     4	
     5	/** Settlement result for one partner on one KST date (KRW, whole won). */
     6	public record DailyLine(LocalDate date, String partnerId, int count, long grossKrw, long feeKrw) {
     7	    public long netKrw() { return grossKrw - feeKrw; }
     8	}
     9	package util;
    10	
    11	import java.math.BigDecimal;
    12	import java.math.RoundingMode;
    13	import java.text.DecimalFormat;
    14	import java.text.DecimalFormatSymbols;
    15	import java.util.Locale;
    16	
    17	/** KRW arithmetic shared by settlement and reporting. */
    18	public final class Money {
    19	    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);
    20	
    21	    private Money() {}
    22	
    23	    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    24	    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
    25	        return amount.multiply(rate)
    26	                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
    27	                .longValueExact();
    28	    }
    29	
    30	    /** Commission on gross KRW; partner contract truncates fractional won. */
    31	    public static long fee(long grossKrw, int feeBps) {
    32	        if (grossKrw <= 0 || feeBps <= 0) return 0;
    33	        return BigDecimal.valueOf(grossKrw)
    34	                .multiply(BigDecimal.valueOf(feeBps))
    35	                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
    36	                .longValueExact();
    37	    }
    38	
    39	    public static String won(long krw) {
    40	        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
    41	        return f.format(krw);
    42	    }
    43	
    44	    public static String rate(BigDecimal rate) {
    45	        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
    46	        return f.format(rate);
    47	    }
    48	}

